document.addEventListener('DOMContentLoaded', () => {
const yearSpan = document.getElementById('year');
if (yearSpan) {
yearSpan.textContent = new Date().getFullYear();
}
const navbar = document.getElementById('navbar');
const siteHeader = document.getElementById('siteHeader');
window.addEventListener('scroll', () => {
if (window.scrollY > 40) {
if (navbar) navbar.classList.add('scrolled');
if (siteHeader) siteHeader.classList.add('scrolled');
} else {
if (navbar && !navbar.hasAttribute('data-permanent-scrolled')) {
navbar.classList.remove('scrolled');
}
if (siteHeader && !siteHeader.hasAttribute('data-permanent-scrolled')) {
siteHeader.classList.remove('scrolled');
}
}
});
const mobileToggle = document.querySelector('.mobile-toggle');
const navLinksContainer = document.querySelector('.nav-links');
const allLinks = document.querySelectorAll('.nav-link, .dropdown-item, .mobile-drawer-cta .btn');
const toggleIcon = mobileToggle ? mobileToggle.querySelector('i') : null;
if (mobileToggle && navLinksContainer) {
mobileToggle.setAttribute('aria-expanded', 'false');
mobileToggle.setAttribute('aria-label', 'Toggle navigation menu');
const closeMobileMenu = () => {
navLinksContainer.classList.remove('nav-active');
mobileToggle.setAttribute('aria-expanded', 'false');
if (toggleIcon) {
toggleIcon.classList.remove('fa-times');
toggleIcon.classList.add('fa-bars');
}
};
const openMobileMenu = () => {
navLinksContainer.classList.add('nav-active');
mobileToggle.setAttribute('aria-expanded', 'true');
if (toggleIcon) {
toggleIcon.classList.remove('fa-bars');
toggleIcon.classList.add('fa-times');
}
};
mobileToggle.addEventListener('click', (e) => {
e.stopPropagation();
if (navLinksContainer.classList.contains('nav-active')) {
closeMobileMenu();
} else {
openMobileMenu();
}
});
allLinks.forEach(link => {
link.addEventListener('click', () => {
if (window.innerWidth <= 1024) {
closeMobileMenu();
}
});
});
document.addEventListener('keydown', (e) => {
if (e.key === 'Escape' && navLinksContainer.classList.contains('nav-active')) {
closeMobileMenu();
}
});
document.addEventListener('click', (e) => {
if (navLinksContainer.classList.contains('nav-active') && navbar && !navbar.contains(e.target)) {
closeMobileMenu();
}
});
}
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
anchor.addEventListener('click', function (e) {
const targetId = this.getAttribute('href');
if (targetId === '#') return;
const targetElement = document.querySelector(targetId);
if (targetElement) {
e.preventDefault();
targetElement.scrollIntoView({
behavior: 'smooth'
});
}
});
});
const fadeElements = document.querySelectorAll('.fade-in-up');
const observerOptions = {
root: null,
rootMargin: '0px',
threshold: 0.15
};
const fadeObserver = new IntersectionObserver((entries, observer) => {
entries.forEach(entry => {
if (entry.isIntersecting) {
entry.target.classList.add('visible');
observer.unobserve(entry.target);
}
});
}, observerOptions);
fadeElements.forEach(element => {
fadeObserver.observe(element);
});
const quoteForm = document.getElementById('quoteForm');
if (quoteForm) {
quoteForm.addEventListener('submit', async (e) => {
e.preventDefault();
const btn = quoteForm.querySelector('button[type="submit"]');
const originalText = btn.innerHTML;
btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Sending Inquiry...';
btn.disabled = true;
const ACCESS_KEY = "8a239cb1-82ea-45ab-b5ca-a4c321bfa17a";
if (ACCESS_KEY === "YOUR_ACCESS_KEY_HERE" || ACCESS_KEY === "") {
alert("Please add your Web3Forms Access Key to script.js to send emails directly.");
btn.innerHTML = '<i class="fas fa-exclamation-triangle"></i> Setup Required';
btn.style.backgroundColor = '#e74c3c';
btn.style.color = '#fff';
setTimeout(() => {
btn.innerHTML = originalText;
btn.disabled = false;
btn.style.backgroundColor = '';
btn.style.color = '';
}, 4000);
return;
}
const name = document.getElementById('name').value;
const company = document.getElementById('company').value;
const email = document.getElementById('email').value;
const phone = document.getElementById('phone').value;
const interestElement = document.getElementById('interest');
const interest = interestElement.options[interestElement.selectedIndex].text;
const message = document.getElementById('message').value;
try {
const response = await fetch('https://api.web3forms.com/submit', {
method: 'POST',
headers: {
'Content-Type': 'application/json',
'Accept': 'application/json'
},
body: JSON.stringify({
access_key: ACCESS_KEY,
subject: 'New B2B Website Inquiry from: ' + name,
from_name: 'Biharilal Fashions Website',
name: name,
company: company,
email: email,
phone: phone,
interest: interest,
message: message
})
});
const json = await response.json();
if (response.status === 200) {
btn.innerHTML = '<i class="fas fa-check"></i> Inquiry Sent Successfully';
btn.style.backgroundColor = '#27ae60';
btn.style.color = '#fff';
quoteForm.reset();
const popup = document.getElementById('successPopup');
if (popup) {
popup.classList.add('show');
setTimeout(() => {
popup.classList.remove('show');
}, 6000);
}
} else {
console.log(response);
btn.innerHTML = '<i class="fas fa-exclamation-triangle"></i> Sending Failed';
btn.style.backgroundColor = '#e74c3c';
btn.style.color = '#fff';
}
} catch (error) {
console.log(error);
btn.innerHTML = '<i class="fas fa-exclamation-triangle"></i> Network Error';
btn.style.backgroundColor = '#e74c3c';
btn.style.color = '#fff';
}
setTimeout(() => {
btn.innerHTML = originalText;
btn.disabled = false;
btn.style.backgroundColor = '';
btn.style.color = '';
}, 4000);
});
}
const careerForm = document.getElementById('careerForm');
if (careerForm) {
careerForm.addEventListener('submit', async (e) => {
e.preventDefault();
const btn = careerForm.querySelector('button[type="submit"]');
const originalText = btn.innerHTML;
btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Submitting Application...';
btn.disabled = true;
const ACCESS_KEY = "8a239cb1-82ea-45ab-b5ca-a4c321bfa17a";
const formData = new FormData();
formData.append('access_key', ACCESS_KEY);
const firstName = document.getElementById('firstName').value;
const lastName = document.getElementById('lastName').value;
const fullName = `${firstName} ${lastName}`;
formData.append('subject', 'New Job Application: ' + fullName);
formData.append('from_name', 'Biharilal Fashions Careers');
formData.append('name', fullName);
formData.append('email', document.getElementById('email').value);
formData.append('phone', document.getElementById('phone').value);
const deptElement = document.getElementById('department');
formData.append('department', deptElement.options[deptElement.selectedIndex].text);
formData.append('coverLetter', document.getElementById('coverLetter').value);
const resumeFile = document.getElementById('resume').files[0];
if (resumeFile) {
formData.append('resume', resumeFile);
}
try {
const response = await fetch('https://api.web3forms.com/submit', {
method: 'POST',
body: formData
});
const json = await response.json();
if (response.status === 200) {
btn.innerHTML = '<i class="fas fa-check"></i> Application Sent Successfully';
btn.style.backgroundColor = '#27ae60';
btn.style.color = '#fff';
careerForm.reset();
const popup = document.getElementById('successPopup');
if (popup) {
popup.classList.add('show');
setTimeout(() => {
popup.classList.remove('show');
}, 6000);
}
} else {
console.log(response);
btn.innerHTML = '<i class="fas fa-exclamation-triangle"></i> Submission Failed';
btn.style.backgroundColor = '#e74c3c';
btn.style.color = '#fff';
}
} catch (error) {
console.log(error);
btn.innerHTML = '<i class="fas fa-exclamation-triangle"></i> Network Error';
btn.style.backgroundColor = '#e74c3c';
btn.style.color = '#fff';
}
setTimeout(() => {
btn.innerHTML = originalText;
btn.disabled = false;
btn.style.backgroundColor = '';
btn.style.color = '';
}, 4000);
});
}
setTimeout(() => {
fadeElements.forEach(element => {
const rect = element.getBoundingClientRect();
if (rect.top < window.innerHeight) {
element.classList.add('visible');
}
});
}, 100);
const closePopupBtn = document.getElementById('closePopup');
if (closePopupBtn) {
closePopupBtn.addEventListener('click', () => {
document.getElementById('successPopup').classList.remove('show');
});
}
});